# Widget 可复用模式

生成 widget 时，按需引入以下模式。每个模式自包含，直接内联到 widget 文件中。

---

## 1. 可拖拽定位

让 widget 可被鼠标拖拽移动，位置自动存入 localStorage。

**使用场景**：用户希望自由调整 widget 位置

**要点**：
- 使用 `useRef` 获取 DOM 元素
- 纯 DOM 事件实现拖拽（mousedown/mousemove/mouseup）
- `className` 中不要设 `bottom/top/left/right`，由组件内 state 控制
- 必须移除 `pointer-events: none`

```jsx
import { React } from 'uebersicht'

export const refreshFrequency = false

export const className = `
  position: fixed;
  font-family: -apple-system, BlinkMacSystemFont, 'SF Pro Display', sans-serif;
`

const WIDGET_ID = 'my-widget'

const DraggableWidget = () => {
  const { useState, useEffect, useRef, useCallback } = React
  const storageKey = `oc-pos-${WIDGET_ID}`
  const saved = JSON.parse(localStorage.getItem(storageKey) || 'null')
  const [pos, setPos] = useState(saved || { x: 200, y: 200 })
  const dragging = useRef(false)
  const offset = useRef({ x: 0, y: 0 })

  const onMouseDown = useCallback((e) => {
    dragging.current = true
    offset.current = { x: e.clientX - pos.x, y: e.clientY - pos.y }
    e.preventDefault()
  }, [pos])

  useEffect(() => {
    const onMove = (e) => {
      if (!dragging.current) return
      const next = { x: e.clientX - offset.current.x, y: e.clientY - offset.current.y }
      setPos(next)
      localStorage.setItem(storageKey, JSON.stringify(next))
    }
    const onUp = () => { dragging.current = false }
    window.addEventListener('mousemove', onMove)
    window.addEventListener('mouseup', onUp)
    return () => {
      window.removeEventListener('mousemove', onMove)
      window.removeEventListener('mouseup', onUp)
    }
  }, [])

  return (
    <div
      onMouseDown={onMouseDown}
      style={{
        position: 'fixed',
        left: pos.x,
        top: pos.y,
        cursor: 'grab',
        userSelect: 'none',
      }}
    >
      {/* widget 内容 */}
    </div>
  )
}

export const render = () => <DraggableWidget />
```

---

## 2. 状态持久化（localStorage）

widget 被 Übersicht 重新 mount 时恢复之前的状态，防止状态丢失。

**使用场景**：计时器、计数器、待办列表等需要持久状态的 widget

```jsx
// 封装 hook：用法和 useState 一致，自动读写 localStorage
const usePersistedState = (key, initial) => {
  const { useState, useEffect } = React
  const storageKey = `oc-${key}`
  const [value, setValue] = useState(() => {
    const saved = localStorage.getItem(storageKey)
    return saved !== null ? JSON.parse(saved) : initial
  })

  useEffect(() => {
    localStorage.setItem(storageKey, JSON.stringify(value))
  }, [value])

  return [value, setValue]
}

// 用法示例
const Widget = () => {
  const [count, setCount] = usePersistedState('counter', 0)
  return <div onClick={() => setCount(c => c + 1)}>{count}</div>
}
```

---

## 3. Shell 输出安全解析

command 的 stdout 可能包含换行、空值、特殊字符。统一用分隔符 + 安全解析。

**使用场景**：所有使用 `command` 获取数据的 widget

```jsx
// command 中用 ||| 作分隔符
export const command = `
  echo "field1:$(some_command)"
  echo "field2:$(other_command)"
`

// 安全解析函数
const parseOutput = (raw, fields) => {
  const result = {}
  fields.forEach(f => { result[f] = '?' })
  if (!raw) return result
  raw.trim().split('\n').forEach(line => {
    const idx = line.indexOf(':')
    if (idx > -1) {
      const key = line.slice(0, idx).trim()
      const val = line.slice(idx + 1).trim()
      if (fields.includes(key)) result[key] = val
    }
  })
  return result
}

// 用法
export const render = ({ output }) => {
  const data = parseOutput(output, ['field1', 'field2'])
  return <div>{data.field1}</div>
}
```

---

## 4. 条件渲染 + 占位符

command 首次执行前 output 为空，避免闪烁或显示错误。

**使用场景**：所有 command-based widget

```jsx
export const render = ({ output, error }) => {
  if (error) return <div style={{ color: 'rgba(255,80,80,0.8)' }}>Error</div>
  if (!output) return <div style={{ opacity: 0.3 }}>Loading...</div>

  // 正常渲染
  return <div>{output.trim()}</div>
}
```

---

export const command = `
  echo "time:$(date '+%H:%M:%S')"
  echo "weekday:$(date '+%A')"
  echo "datestr:$(date '+%Y年%-m月%-d日')"
`

export const refreshFrequency = 1000

export const className = `
  position: fixed;
  bottom: 90px;
  right: 40px;
  text-align: right;
  pointer-events: none;
  font-family: -apple-system, BlinkMacSystemFont, 'SF Pro Display', sans-serif;
  color: rgba(255, 255, 255, 0.92);
  text-shadow: 0 1px 4px rgba(0, 0, 0, 0.6);
`

export const render = ({ output }) => {
  const lines = {}
  ;(output || '').split('\n').forEach(line => {
    const idx = line.indexOf(':')
    if (idx > -1) lines[line.slice(0, idx)] = line.slice(idx + 1)
  })

  const [hh, mm, ss] = (lines.time || '--:--:--').split(':')

  return (
    <div>
      <div style={{
        fontSize: '72px',
        fontWeight: '200',
        letterSpacing: '-3px',
        lineHeight: 1,
      }}>
        {hh}:{mm}
        <span style={{ fontSize: '36px', opacity: 0.5, marginLeft: '6px' }}>:{ss}</span>
      </div>
      <div style={{
        fontSize: '15px',
        opacity: 0.65,
        marginTop: '8px',
        letterSpacing: '0.5px',
      }}>
        {lines.datestr}　{lines.weekday}
      </div>
    </div>
  )
}

export const command = `
  # Get commit counts per date for the last 12 weeks
  echo "---COMMITS---"
  find ~ -maxdepth 3 -name ".git" -type d 2>/dev/null | head -10 | while read gitdir; do
    repodir="$(dirname "$gitdir")"
    git -C "$repodir" log --format="%Y-%m-%d" --since="12 weeks ago" 2>/dev/null
  done | sort | uniq -c | awk '{print $1, $2}'

  # Get today's commits per repo for "most active repo"
  echo "---REPOS---"
  today=$(date '+%Y-%m-%d')
  find ~ -maxdepth 3 -name ".git" -type d 2>/dev/null | head -10 | while read gitdir; do
    repodir="$(dirname "$gitdir")"
    reponame="$(basename "$repodir")"
    count=$(git -C "$repodir" log --format="%Y-%m-%d" --since="$today 00:00" 2>/dev/null | wc -l | tr -d ' ')
    if [ "$count" -gt 0 ] 2>/dev/null; then
      echo "$count $reponame"
    fi
  done | sort -rn | head -1

  # Get current branch of the most recently modified repo
  echo "---BRANCH---"
  find ~ -maxdepth 3 -name ".git" -type d 2>/dev/null | head -10 | while read gitdir; do
    repodir="$(dirname "$gitdir")"
    modtime=$(stat -f "%m" "$repodir/.git" 2>/dev/null || echo "0")
    echo "$modtime $repodir"
  done | sort -rn | head -1 | awk '{print $2}' | while read repodir; do
    git -C "$repodir" branch --show-current 2>/dev/null
  done
`

export const refreshFrequency = 300000

export const className = `
  position: fixed;
  top: 40px;
  right: 40px;
  font-family: -apple-system, BlinkMacSystemFont, 'SF Mono', 'Menlo', monospace;
  pointer-events: none;
`

const WEEKS = 12
const DAYS_TOTAL = WEEKS * 7
const CELL_SIZE = 12
const CELL_GAP = 3
const DAY_LABELS = ['Mon', '', 'Wed', '', 'Fri', '', '']
const MONTH_NAMES = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']

const getColor = (count) => {
  if (count <= 0) return 'rgba(255,255,255,0.05)'
  if (count <= 2) return '#0e4429'
  if (count <= 5) return '#006d32'
  if (count <= 9) return '#26a641'
  return '#39d353'
}

const parseOutput = (raw) => {
  const result = {
    commits: {},
    topRepo: '',
    todayRepoCount: 0,
    branch: '',
  }
  if (!raw) return result

  const text = raw.trim()
  const commitSection = text.split('---COMMITS---')[1]?.split('---REPOS---')[0] || ''
  const repoSection = text.split('---REPOS---')[1]?.split('---BRANCH---')[0] || ''
  const branchSection = text.split('---BRANCH---')[1] || ''

  // Parse commit counts
  commitSection.trim().split('\n').forEach(line => {
    const trimmed = line.trim()
    if (!trimmed) return
    const parts = trimmed.split(/\s+/)
    if (parts.length >= 2) {
      const count = parseInt(parts[0], 10)
      const date = parts[1]
      if (!isNaN(count) && /^\d{4}-\d{2}-\d{2}$/.test(date)) {
        result.commits[date] = (result.commits[date] || 0) + count
      }
    }
  })

  // Parse top repo
  const repoLine = repoSection.trim().split('\n')[0]?.trim()
  if (repoLine) {
    const parts = repoLine.split(/\s+/)
    if (parts.length >= 2) {
      result.todayRepoCount = parseInt(parts[0], 10) || 0
      result.topRepo = parts.slice(1).join(' ')
    }
  }

  // Parse branch
  result.branch = branchSection.trim().split('\n')[0]?.trim() || ''

  return result
}

const formatDate = (d) => {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`
}

// Convert JS getDay (0=Sun) to row index (0=Mon, 6=Sun)
const jsToRow = (jsDay) => jsDay === 0 ? 6 : jsDay - 1

const buildGrid = (commits) => {
  const today = new Date()
  today.setHours(0, 0, 0, 0)
  const todayRow = jsToRow(today.getDay())

  // The rightmost column (col = WEEKS-1) contains today.
  // We need to find the Saturday (or Sunday) that starts the first column.
  // Going back from today: the last column started on the Monday of this week.
  // Today is at row=todayRow in col=WEEKS-1.
  // The first day on the grid is at row=0, col=0 (a Monday).
  // Days back from today to that Monday:
  //   (WEEKS - 1) * 7 + todayRow
  const daysBack = (WEEKS - 1) * 7 + todayRow

  const grid = []
  for (let r = 0; r < 7; r++) {
    grid[r] = []
    for (let c = 0; c < WEEKS; c++) {
      grid[r][c] = { date: null, count: 0 }
    }
  }

  const monthLabels = []
  const seenMonths = new Set()

  // Fill grid: iterate each cell by (col, row) order
  // offset=0 corresponds to the earliest date (row=0, col=0), which is a Monday
  // offset=daysBack corresponds to today
  for (let col = 0; col < WEEKS; col++) {
    for (let row = 0; row < 7; row++) {
      const offset = col * 7 + row
      // Cells beyond today in the last partial column are future dates
      if (offset > daysBack) continue
      const d = new Date(today)
      d.setDate(today.getDate() - (daysBack - offset))
      const dateStr = formatDate(d)
      grid[row][col] = { date: dateStr, count: commits[dateStr] || 0 }

      // Track month boundaries (when row=0, i.e. Monday of each week)
      if (row === 0) {
        const monthKey = `${d.getFullYear()}-${d.getMonth()}`
        if (!seenMonths.has(monthKey)) {
          seenMonths.add(monthKey)
          monthLabels.push({ col, label: MONTH_NAMES[d.getMonth()] })
        }
      }
    }
  }

  return { grid, monthLabels }
}

const computeStats = (commits) => {
  const today = new Date()
  today.setHours(0, 0, 0, 0)
  const todayStr = formatDate(today)
  const todayCount = commits[todayStr] || 0

  // Calculate streak: consecutive days with commits ending at today (or yesterday if today has 0)
  let streak = 0
  let checkDate = new Date(today)
  if (!commits[todayStr]) {
    checkDate.setDate(checkDate.getDate() - 1)
  }
  for (let i = 0; i < DAYS_TOTAL; i++) {
    const ds = formatDate(checkDate)
    if (commits[ds] && commits[ds] > 0) {
      streak++
      checkDate.setDate(checkDate.getDate() - 1)
    } else {
      break
    }
  }

  // Total commits in 12 weeks
  let total = 0
  Object.values(commits).forEach(c => { total += c })

  return { todayCount, streak, total }
}

const GitPulseInner = ({ output }) => {
  const data = parseOutput(output)
  const { grid, monthLabels } = buildGrid(data.commits)
  const stats = computeStats(data.commits)

  const labelWidth = 28
  const gridWidth = WEEKS * (CELL_SIZE + CELL_GAP) - CELL_GAP
  const monthLabelHeight = 16

  return (
    <div style={{
      background: 'rgba(0, 0, 0, 0.5)',
      backdropFilter: 'blur(24px)',
      WebkitBackdropFilter: 'blur(24px)',
      borderRadius: '16px',
      border: '1px solid rgba(255,255,255,0.08)',
      padding: '16px 18px 14px',
      color: 'rgba(255,255,255,0.9)',
      minWidth: `${labelWidth + gridWidth + 20}px`,
    }}>
      {/* Header */}
      <div style={{
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        marginBottom: '12px',
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
          <div style={{
            width: '8px',
            height: '8px',
            borderRadius: '50%',
            background: stats.todayCount > 0 ? '#39d353' : 'rgba(255,255,255,0.2)',
            boxShadow: stats.todayCount > 0 ? '0 0 6px rgba(57,211,83,0.5)' : 'none',
          }} />
          <span style={{
            fontSize: '12px',
            fontWeight: 600,
            letterSpacing: '0.5px',
            color: 'rgba(255,255,255,0.8)',
          }}>
            Git Pulse
          </span>
          {data.branch && (
            <span style={{
              fontSize: '10px',
              color: 'rgba(255,255,255,0.35)',
              background: 'rgba(255,255,255,0.06)',
              padding: '2px 6px',
              borderRadius: '4px',
            }}>
              {data.branch}
            </span>
          )}
        </div>
        <div style={{
          fontSize: '11px',
          color: stats.streak > 0 ? '#39d353' : 'rgba(255,255,255,0.35)',
          fontWeight: 600,
        }}>
          {stats.streak > 0 ? `${stats.streak}d streak` : 'no streak'}
        </div>
      </div>

      {/* Month labels */}
      <div style={{
        display: 'flex',
        marginLeft: `${labelWidth}px`,
        marginBottom: '4px',
        height: `${monthLabelHeight}px`,
        position: 'relative',
        width: `${gridWidth}px`,
      }}>
        {monthLabels.map((m, i) => (
          <span key={i} style={{
            position: 'absolute',
            left: `${m.col * (CELL_SIZE + CELL_GAP)}px`,
            fontSize: '9px',
            color: 'rgba(255,255,255,0.3)',
            letterSpacing: '0.3px',
          }}>
            {m.label}
          </span>
        ))}
      </div>

      {/* Heatmap grid */}
      <div style={{ display: 'flex', gap: '0px' }}>
        {/* Day labels */}
        <div style={{
          display: 'flex',
          flexDirection: 'column',
          gap: `${CELL_GAP}px`,
          marginRight: '4px',
          width: `${labelWidth - 4}px`,
        }}>
          {DAY_LABELS.map((label, i) => (
            <div key={i} style={{
              height: `${CELL_SIZE}px`,
              fontSize: '9px',
              color: 'rgba(255,255,255,0.25)',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'flex-end',
              paddingRight: '4px',
            }}>
              {label}
            </div>
          ))}
        </div>

        {/* Grid columns */}
        <div style={{ display: 'flex', gap: `${CELL_GAP}px` }}>
          {Array.from({ length: WEEKS }, (_, col) => (
            <div key={col} style={{ display: 'flex', flexDirection: 'column', gap: `${CELL_GAP}px` }}>
              {Array.from({ length: 7 }, (_, row) => {
                const cell = grid[row][col]
                const color = getColor(cell.count)
                return (
                  <div key={row} style={{
                    width: `${CELL_SIZE}px`,
                    height: `${CELL_SIZE}px`,
                    borderRadius: '2px',
                    background: color,
                    transition: 'background 0.3s ease',
                  }} />
                )
              })}
            </div>
          ))}
        </div>
      </div>

      {/* Footer */}
      <div style={{
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        marginTop: '12px',
        paddingTop: '10px',
        borderTop: '1px solid rgba(255,255,255,0.06)',
      }}>
        <div style={{ fontSize: '11px', color: 'rgba(255,255,255,0.5)' }}>
          <span style={{ color: 'rgba(255,255,255,0.8)', fontWeight: 600 }}>{stats.todayCount}</span>
          <span> commit{stats.todayCount !== 1 ? 's' : ''} today</span>
        </div>
        <div style={{ fontSize: '10px', color: 'rgba(255,255,255,0.3)' }}>
          {data.topRepo
            ? <span>{data.topRepo}</span>
            : <span>{stats.total} in 12w</span>
          }
        </div>
      </div>

      {/* Legend */}
      <div style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'flex-end',
        gap: '4px',
        marginTop: '8px',
      }}>
        <span style={{ fontSize: '9px', color: 'rgba(255,255,255,0.25)', marginRight: '4px' }}>Less</span>
        {[0, 1, 3, 6, 10].map((level, i) => (
          <div key={i} style={{
            width: '8px',
            height: '8px',
            borderRadius: '2px',
            background: getColor(level),
          }} />
        ))}
        <span style={{ fontSize: '9px', color: 'rgba(255,255,255,0.25)', marginLeft: '4px' }}>More</span>
      </div>
    </div>
  )
}

export const render = ({ output }) => {
  return <GitPulseInner output={output} />
}

export const command = `date '+%H:%M:%S|||%Y年%-m月%-d日|||%A'`

export const refreshFrequency = 1000

export const className = `
  position: fixed;
  bottom: 90px;
  left: 50%;
  transform: translateX(-50%);
  width: 400px;
  height: 140px;
  border-radius: 16px;
  overflow: hidden;
  pointer-events: none;
  font-family: -apple-system, BlinkMacSystemFont, 'SF Pro Display', sans-serif;
`

// ---------------------------------------------------------------------------
// Color interpolation helpers
// ---------------------------------------------------------------------------
function hexToRgb(hex) {
  const n = parseInt(hex.replace('#', ''), 16)
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255]
}

function rgbToHex([r, g, b]) {
  return '#' + [r, g, b].map(v => v.toString(16).padStart(2, '0')).join('')
}

function lerpColor(a, b, t) {
  const ra = hexToRgb(a)
  const rb = hexToRgb(b)
  return rgbToHex(ra.map((v, i) => Math.round(v + (rb[i] - v) * t)))
}

// ---------------------------------------------------------------------------
// Sky gradient calculation
// ---------------------------------------------------------------------------
const SKY_STOPS = [
  { hour: 0,  top: '#0a0e27', bot: '#1a1a4e' },
  { hour: 5,  top: '#0a0e27', bot: '#1a1a4e' },
  { hour: 6,  top: '#1a1a4e', bot: '#ff6b35' },
  { hour: 7,  top: '#ffd700', bot: '#ff6b35' },
  { hour: 8,  top: '#87CEEB', bot: '#a8d8ea' },
  { hour: 12, top: '#4a90d9', bot: '#87CEEB' },
  { hour: 15, top: '#4a90d9', bot: '#6ab0de' },
  { hour: 17, top: '#ff8c00', bot: '#ffa040' },
  { hour: 18, top: '#ff4500', bot: '#ff6b35' },
  { hour: 19, top: '#8b1a1a', bot: '#ff4500' },
  { hour: 20, top: '#2d1b4e', bot: '#8b1a1a' },
  { hour: 21, top: '#2d1b4e', bot: '#1a1a4e' },
  { hour: 24, top: '#0a0e27', bot: '#1a1a4e' },
]

function getSkyGradient(hour, minute) {
  const t = hour + minute / 60
  let lo = SKY_STOPS[0]
  let hi = SKY_STOPS[SKY_STOPS.length - 1]
  for (let i = 0; i < SKY_STOPS.length - 1; i++) {
    if (t >= SKY_STOPS[i].hour && t < SKY_STOPS[i + 1].hour) {
      lo = SKY_STOPS[i]
      hi = SKY_STOPS[i + 1]
      break
    }
  }
  const frac = (hi.hour === lo.hour) ? 0 : (t - lo.hour) / (hi.hour - lo.hour)
  const top = lerpColor(lo.top, hi.top, frac)
  const bot = lerpColor(lo.bot, hi.bot, frac)
  return `linear-gradient(to bottom, ${top}, ${bot})`
}

// ---------------------------------------------------------------------------
// Sun / Moon position along an arc
// ---------------------------------------------------------------------------
function getCelestialPos(hour, minute, width, height) {
  // Sun arc: rises at 6:00 (left edge), peaks at 12:00 (center top), sets at 18:00 (right edge)
  const dayProgress = (hour + minute / 60 - 6) / 12 // 0 at 6:00, 1 at 18:00
  const clampedDay = Math.max(0, Math.min(1, dayProgress))

  // Night arc: moon rises at 18:00, peaks at 0:00, sets at 6:00
  let nightHour = hour + minute / 60
  if (nightHour >= 18) nightHour -= 18
  else nightHour += 6
  const nightProgress = nightHour / 12
  const clampedNight = Math.max(0, Math.min(1, nightProgress))

  const padding = 30
  const arcWidth = width - padding * 2

  const sunX = padding + clampedDay * arcWidth
  const sunY = height - 45 - Math.sin(clampedDay * Math.PI) * (height - 60)

  const moonX = padding + clampedNight * arcWidth
  const moonY = height - 45 - Math.sin(clampedNight * Math.PI) * (height - 60)

  const isDaytime = hour >= 6 && hour < 18
  const sunVisible = hour >= 5 && hour < 19
  const moonVisible = hour >= 18 || hour < 7

  return { sunX, sunY, moonX, moonY, isDaytime, sunVisible, moonVisible }
}

// ---------------------------------------------------------------------------
// City skyline SVG path
// ---------------------------------------------------------------------------
const SKYLINE_PATH = [
  // Start from bottom-left
  'M0,140',
  // Building 1 - short wide
  'L0,105 L15,105 L15,95 L35,95 L35,105 L45,105',
  // Building 2 - medium with flat top
  'L45,80 L55,80 L55,75 L70,75 L70,80 L80,80 L80,105',
  // Building 3 - tall narrow tower with antenna
  'L90,105 L90,60 L95,60 L97,42 L99,60 L104,60 L104,105',
  // Building 4 - medium stepped
  'L115,105 L115,85 L125,85 L125,72 L140,72 L140,85 L150,85 L150,105',
  // Building 5 - short
  'L160,105 L160,92 L180,92 L180,105',
  // Building 6 - tallest skyscraper with spire
  'L190,105 L190,55 L195,55 L198,30 L201,55 L210,55 L210,68 L220,68 L220,105',
