          fontVariantNumeric: 'tabular-nums',
          letterSpacing: '0.3px',
        }}>
          <span>{track ? fmt(track.position) : '0:00'}</span>
          <span>{track ? fmt(track.duration) : '0:00'}</span>
        </div>
      </div>

    </div>
  )
}

